CREATE TABLE IF NOT EXISTS paginas (slug TEXT PRIMARY KEY, titulo TEXT NOT NULL, contenido TEXT NOT NULL, actualizado TEXT NOT NULL DEFAULT (datetime('now')));
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('que-es-aa', '¿Qué es AA?', '<h2><strong>Historia de AA</strong></h2><p>Alcohólicos Anónimos nace un 10 de junio de 1935 en la ciudad de Akron, Ohio en Estados Unidos, cuando dos alcohólicos crónicos: el Dr. Robert H. Smith (Bob S.) y William Griffith Wilson (Bill W.) – cofundadores –, se encuentran y a través del compartimiento de sus experiencias como bebedores problema alcanzan el estado de sobriedad permanente. El éxito de este resultado es basado en la idea de que un alcohólico puede ayudar a otro alcohólico a través de un “puente de comprensión”.</p><p>Ésta es la fecha en que oficialmente se funda Alcohólicos Anónimos y a partir de la cual comienza a desarrollarse el revolucionario y exitoso programa de los “Doce Pasos de A.A.” que ayuda a los alcohólicos a mantenerse en sobriedad. El nombre de A.A. es tomado de la primera publicación del libro “Alcohólicos Anónimos” en el año de 1939 escrito por Bill W.</p><h2><strong>Enunciado</strong></h2><p>Alcohólicos Anónimos® es una comunidad de personas que comparten su mutua experiencia, fortaleza y esperanza para resolver su problema común y ayudar a otros a recuperarse del alcoholismo. El único requisito para ser miembro de AA es el deseo de dejar la bebida. Para ser miembro de AA no se pagan derechos de admisión ni cuotas; nos mantenemos con nuestras propias contribuciones. AA no está afiliada a ninguna secta, religión, partido político, organización o institución alguna; no desea intervenir en controversias, no respalda ni se opone a ninguna causa.</p><p>Nuestro objetivo primordial es mantenernos sobrios y ayudar a otros alcohólicos a alcanzar el estado de sobriedad<strong>.</strong></p><p><strong>(Con el permiso de the AA Grapevine, Inc.)</strong></p><h2><strong>¿Cómo funciona AA?</strong></h2><p>Los miembros hacen uso de su programa de recuperación los “Doce Pasos de A.A” para mantener la sobriedad, mediante un conjunto de principios espirituales, que cuando se practican como una forma de vida pueden eliminar la obsesión por beber.</p><p>Los grupos usan las “Doce Tradiciones” para permanecer unidos. En este sentido destaca la unicidad de propósito que resulta esencial para el tratamiento eficaz del alcoholismo y la tercera tradición que a la letra dice: “El único requisito para ser miembro de A.A es querer dejar de beber”.</p><p>Es decir, sólo aquellos que sufren de adicción al alcohol podrán integrarse a Alcohólicos Anónimos. La experiencia ha demostrado que las personas con otro tipo de adicciones no logran establecer un puente de comprensión, lo que impide experimentar un verdadero sentido espiritual de pertenencia, fundamental en el proceso de recuperación.</p><p>Los grupos de Alcohólicos Anónimos funcionan a través de sesiones en terapia grupal de ayuda mutua, la asistencia es voluntaria y sus servicios son gratuitos.</p><p>En México todos los grupos integrantes de los Servicios Mundiales de Alcohólicos Anónimos registran su grupo en la Oficina de Servicios Generales (OSG) y cuentan con una placa de identidad.</p><h2><strong>¿Cómo ingreso a un grupo?</strong></h2><p>En nuestra página web <a href="/directorio">aabcn02.org/directorio</a> consulta el Directorio Nacional, que contiene los datos de contacto de todos los grupos que existen a nivel nacional para que ubiques el más cercano a tu domicilio.</p><p>Verifica la hora y días de sesión, y preséntate mencionando que deseas información para dejar de beber.</p><p>También puedes llamarnos al teléfono: [TELÉFONO DE OFICINA] y con gusto te brindaremos asesoría.</p><p>No olvides que de acuerdo a nuestra Tercera Tradición: “El único requisito para ser miembro de A.A es querer dejar de beber”.</p><h2><strong>¿Qué NO hace AA?</strong></h2><ul><li><p>No da a los alcohólicos la motivación para recuperarse.</p></li><li><p>No trata de persuadir a los alcohólicos para que se hagan miembros.</p></li><li><p>No patrocina ni participa en investigaciones.</p></li><li><p>No guarda registros de asistencia ni historiales.</p></li><li><p>No está afiliada a consejos ni agencias sociales.</p></li><li><p>No vigila ni trata de controlar a sus miembros.</p></li><li><p>No hace pronósticos ni diagnósticos médicos ni psicológicos.</p></li><li><p>No provee servicios de desintoxicación ni de enfermería y hospitalización, medicinas o cualquier tratamiento médico psiquiátrico.</p></li><li><p>No ofrece servicios religiosos ni organiza ni patrocina retiros.</p></li><li><p>No participa en la educación acerca del alcohol.</p></li><li><p>No proporciona servicios de vivienda, alimentación, ropa, dinero, trabajo, ni demás servicios de asistencia social.</p></li><li><p>No ofrece servicios de consulta doméstica ni profesional.</p></li><li><p>No acepta dinero por sus servicios, ni contribuciones de fuentes no A.A.</p></li><li><p>No suministra cartas de recomendación a las juntas de libertad condicional, abogados o funcionarios de los tribunales, agencias sociales, empleadores.</p></li></ul>');
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('aa-en-mexico', 'AA en México', '<h2><strong>Antecedentes AA en México</strong></h2><h2>En el desarrollo de AA en México, se aprecian tres etapas iniciales: la primera de 1941 a 1946 donde observamos los intentos (generalmente infructuosos) de lograr la sobriedad a nivel individual, por parte de algunos miembros solitarios y la formación de grupos cuyo funcionamiento era inconstante.</h2><p>La segunda etapa empieza a partir del año 1946, cuando un grupo de AA logra funcionar de manera permanente, y la tercera a partir de 1956, año en que comenzaron a funcionar los primeros grupos de habla hispana, formados exclusivamente por miembros mexicanos.</p><p>Un hecho que favoreció el inicio de AA en México, fue el artículo del periodista Jack Alexander, publicado en el Saturday Evening Post en 1941. La nota de que un puñado de hombres había alcanzado la sobriedad a través de esta agrupación, impacto profundamente a la comunidad internacional, llegando a nuestro país, donde llamo la atención de algunos solitarios.</p><p>Ese año, dos personas con problemas de alcoholismo residentes en la Ciudad de México, Arthur H. y Jorge S., leyeron publicaciones con información de Alcohólicos Anónimos®. El primero en el citado artículo de Jack Alexander, y el segundo en una publicación de la Secretaría de Educación Pública que circulo en esa época. Ambos escribieron a la Oficina Central de Nueva York solicitando información, y recibieron respuesta con la literatura que había disponible en aquel tiempo.</p><p>Posteriormente a mediados de los cuarenta, un alcohólico de nombre Gilberto M. recibió el mensaje en Los Angeles, California, lugar a donde había viajado con su esposa en busca de una solución a su problema de alcoholismo. Al regresar a su lugar de origen en Monterrey, N.L., su esposa, la Sra. Francisca Gonzales, tradujo algunos folletos de Alcohólicos Anónimos® al español y su esposo inicio el “Grupo Monterrey”, que llego a contar con 25 miembros, desafortunadamente el grupo solo funciono entre 1945 y 1946.</p><p>No obstante, el 18 de septiembre de 1946, se llevó a cabo la primera junta de información pública en el país, organizada por Ricardo P., un AA de ascendencia mexicana proveniente de Cleveland y Cónsul Honorario de México en esa ciudad, donde proporciono datos, informes y orientación sobre AA en una plática de una sencillez conmovedora; el suceso ocurrió en el “Teatro del Pueblo” en la Ciudad de México. Se sabe que Ricardo fue apoyado por un reportero de “El Universal” que cubrió la noticia y asistió a la plática Este diario publico varios artículos durante ese mes acerca de Alcohólicos anónimos.</p><p>Varios días después, el 25 de septiembre de 1946, se publicó una nota periodística informando el inicio del grupo “Mexico City Group” (Grupo Ciudad de México) considerando el primer grupo formal en nuestro país. Sus iniciadores fueron Lester F. quien solicito a la Oficina Central de Nueva York folletos que indicaran cómo formar un grupo. Este grupo estuvo integrado además por Fernando I., Ramón C. y Jesús A., quien era propietario del departamento donde se llevó a cabo la primera reunión, ubicado en la calle de Gómez Farias 66, Departamento 208. Pauline D., proveniente del grupo de Arlington, Virginia, se integró al grupo en diciembre de ese año.</p><p>El 16 de diciembre de 1956, inició el “Grupo Hospital Central Militar”, siendo el primer grupo de habla hispana. Este hecho sucedió como consecuencia de la ayuda que dio a un miembro de las fuerzas armadas de nombre Joaquín B., quien logro la sobriedad gracias al apoyo del Dr. José Gonzáles Varela, director del Pabellón de Psiquiatría de dicho hospital y de su esposa, la Sra. Irma Reyes de B.</p><p>El 15 de marzo de 1957, Joaquín E., administrador del cementerio Panteón Florido de Mérida, Yucatan, recibió la visita del padre Roberto Menard y del Dr. Carlos Rubio Rojas, ese día le trasmitió el mensaje a Leocadio P., un trabajador del cementerio, dando lugar al inicio del grupo Panteón Florido, primero en Yucatán, el cual tiempo después recibió la visita de Bill W., cofundador de AA.</p><p>Así fueron surgiendo gradualmente los grupos de Alcohólicos Anónimos en nuestro país. En 1961 nacieron los siguientes: 12 de marzo, el grupo Tapatío de Guadalajara, jalisco; el 5 de mayo, el grupo Bolívar de México, D.F.; el 20 de mayo, el grupo Michoacano de morelia, Michoacan y posteriormente muchos otros en diferentes partes del país.</p><p>En abril de 1964, un recuento de la cifra de grupos en nuestro país ascendía a 31, diseminados en el Territorio Nacional. En los datos de crecimiento del número de grupos en México, también se distinguen 3 etapas. Primero se observa un lento crecimiento en la década de los cincuenta. Para los años sesenta este ritmo se vuelve más constante y resuelto. Finalmente, a partir de 1969, registra un espectacular incremento. Sólo en los últimos cuatro años de la década de los ochenta se abrieron tantos grupos como en los casi 40 años anteriores.</p><p>La organización del Primer Congreso Nacional estuvo a cargo de la junta intergrupal de la Ciudad de México. A través de los trabajos preparados por los congresistas se generó un fructífero intercambio de experiencias y se ventilo la problemática del movimiento en el país. Estos congresos empezaron a celebrarse desde1964, dos cada año. A partir de 1973, tuvieron una periodicidad anual con algunas excepciones. El último fue el 26° Congreso Nacional celebrado en Tuxtla Gutiérrez, Chiapas, en 1985.</p><p>Estos congresos marcaron el inicio de una época de AA en México, en la que se llegó, entre otras a las siguientes conclusiones: crear en la Capital Mexicana la Oficina de Servicios Generales y solicitar a la O.S.G. de Nueva York la autorización para elaborar toda la Literatura de AA en español.</p><p>Así durante el 6° Congreso Nacional, se tomó la decisión de que la oficina intergrupal de la Ciudad de México, hiciera las veces de Oficina de Servicios Generales, mientras está era creada. En el 9° Congreso Nacional se decidió nombrar un comité encargado de planear la formación de los Servicios Generales en México; esto sucedió en 1968.</p><p>La Primera Asamblea Mexicana se llevó a cabo los días 21, 22 y 23 de marzo de 1969, en la Ciudad de México, con la asistencia de 23 delegados provenientes de 14 entidades del país, y sirvió para comenzar a buscar bases para que iniciaran los Servicios Generales en México.</p><p>En la Segunda Asamblea Mexicana, realizada los días 14, 15 y 16 de septiembre de 1969, se acordó que entrara en función la Oficina de Servicios Generales el 9 de diciembre de ese año, quedando formalmente constituida con domicilio en Gabriel Leyva No. 26, Despacho. 305. En esta Reunión Alcohólicos Anónimos® en nuestro país “llego a la mayoría de edad”, cuando aceptó el “Tercer Legado”, el 16 de septiembre de 1969.</p><p>Desde esa fecha, anualmente se celebra esta reunión que hasta la 27ª Asamblea Mexicana se denominó con ese nombre. A partir de la 28ª cambio a Conferencia Mexicana de Servicios Generales de Alcohólicos Anónimos, en la que se consideran los asuntos de interés general para Alcohólicos Anónimos® en su totalidad, se salvaguardan las Tradiciones y son la voz de la conciencia de nuestra agrupación.</p><p>La Central Mexicana de Servicios Generales de Alcohólicos Anónimos de acuerdo a su acta constitutiva es una Asociación Civil no lucrativa integrada actualmente por la Oficina de Servicios Generales y la Oficina Plenitud AA. Tiene como objetivo prestar servicios y llevar a cabo actividades para ayudar a la recuperación de las personas que padecen la enfermedad del alcoholismo a través del programa de Alcohólicos Anónimos®, así como imprimir y distribuir la literatura de AA y es la única poseedora de los derechos de autor en nuestro país.</p><p>La inquietud de celebrar las Convenciones Nacionales cada cuatro años, se manifestó en la 7ª Asamblea Mexicana en 1973 y posteriormente en la 9ª en 1975, cuando el entonces Comité de Agenda y Admisión recomendó que se realizara la Convención Nacional, y que fuera organizada por un comité designado por la asamblea estatal. A partir de entonces iniciaron los trabajos para organizar la Primera Convención Nacional en 1976, fecha desde la cual se han celebrado 13 ediciones, las primeras cinco en la Ciudad de México, y después una en cada región.</p><p>La Central Mexicana de Servicios Generales de Alcohólicos Anónimos, A.C., actualmente cuenta con más de 14,000 grupos distribuidos a lo largo del país, 2 Territorios, 6 Regiones y 83 Áreas, así como un número aproximado de 110 mil miembros en recuperación dispuestos a trasmitir el mensaje de manera voluntaria. Actualmente Alcohólicos Anónimos® tiene presencia en aproximadamente 180 países alrededor del mundo.</p>');
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('osg', '¿Qué es la OSG?', '<h2><strong>Historia</strong></h2><p>Debido a las necesidades de ese entonces, de contar con un centro de información y de servicio a nivel nacional, el 9 de diciembre de 1969, se funda la <strong>Oficina de Servicios Generales de Alcohólicos Anónimos (OSG)</strong> en calle de Gabriel Leyva 26 en Centro Histórico de la CDMX. Sin embargo, para que la comunidad de A.A. tuviera un carácter legal, se constituyó el 10 de marzo de 1970, la <strong>Central Mexicana de Servicios Generales de Alcohólicos Anónimos, A.C.</strong></p><h2><strong>¿Cuáles son sus servicios?</strong></h2><p>La <strong>OSG</strong> sirve a todos los grupos de AA en México y también ofrece sus servicios a los AA de otros países, especialmente a los que no tienen estructura de servicio. Funciona como un centro de intercambio de información de la experiencia de AA acumulada a lo largo de los años, coordina una amplia gama de actividades, servicios y supervisa la publicación, traducción y distribución de la literatura de AA aprobada por la conferencia y de los materiales de servicio.</p><ul><li><p>Reunión de internacionales y solitarios.</p></li><li><p>Ayuda a grupos en instituciones de tratamiento y correccionales.</p></li><li><p>Información pública.</p></li><li><p>Rupturas de anonimato.</p></li><li><p>Cooperación con la comunidad profesional.</p></li><li><p>Auto mantenimiento.</p></li><li><p>Coordina la reunión anual de la Conferencia Mexicana.</p></li><li><p>Coordina las actividades de las convenciones nacionales.</p></li><li><p>Registro de grupos.</p></li><li><p>Servicios de directorios.</p></li><li><p>Apoyo a reuniones de servicio.</p></li></ul><p>Se invita a los visitantes a la Ciudad de México a hacer un recorrido con guía por las instalaciones de la OSG y oficina Plenitud.</p><p>O visítanos a través de un <a href="https://aamexico.org/virtual_AA/aa.html" target="_blank" rel="noopener">Recorrido Virtual de la OSG</a></p><h2><strong>¿Por qué la OSG necesita de aportaciones voluntarias?</strong></h2><p>Todas las actividades y servicios que desde la OSG se brindan implican un gasto, así como el pago de renta de las oficinas, luz, empleados etc., que no podría cubrirse sin las aportaciones de los miembros de AA.</p><p>En este sentido, es importante mencionar que de acuerdo a la séptima tradición los grupos de A.A. deben mantenerse con recursos propios. <strong>“Cada grupo de A.A. debe mantenerse completamente así mismo, negándose a recibir contribuciones de afuera”.</strong></p><p>De ahí la importancia de que los miembros de la comunidad realicen sus donaciones.</p><h2><strong>¿Qué es la RIS?</strong></h2><p><strong>R.I.S.</strong> significa <strong>Reunión de Internacionales y Solitarios de Alcohólicos Anónimos</strong>, y es el servicio que facilita la <strong>Oficina de Servicios Generales</strong> para ayudar a aquellos <strong>Alcohólicos Anónimos</strong> que, por diversos motivos, no pueden acudir a las reuniones de los grupos a mantener su sobriedad.</p>');
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('comites', 'Comités de servicio', '<h2>Aquí encontraras información sobre las actividades que realiza cada comité de servicio en AA, así como los distintos recursos disponibles para facilitar las actividades de servicio de cada comité.</h2><ul><li><p><a href="/pagina?p=comite-agenda">Comité de Agenda.</a></p></li><li><p><a href="/pagina?p=comite-archivos-historicos">Comité de Archivos Históricos.</a></p></li><li><p><a href="/pagina?p=comite-ccp">Comité de Cooperación entre la Comunidad Profesional.</a></p></li><li><p><a href="/pagina?p=comite-finanzas">Comité de Finanzas.</a></p></li><li><p><a href="/pagina?p=comite-cip">Comité de Información Pública.</a></p></li><li><p><a href="/pagina?p=comite-cic">Comité de Instituciones Correccionales.</a></p></li><li><p><a href="/pagina?p=comite-literatura">Comité de Literatura.</a></p></li><li><p><a href="/pagina?p=comite-plenitud">Comité de Plenitud.</a></p></li><li><p><a href="/pagina?p=comite-cta">Comité de Tratamiento y Accesibilidades.</a></p></li></ul><p>Si estás interesado en participar como servidor en algún comité, consulta está información y acércate al RSG de tu grupo o MCD de tu distrito para informarte como puedes integrarte a un comité.</p>');
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('comite-agenda', 'Comité de Agenda', '<h2><strong>Comité de Agenda/Conferencia</strong></h2><h3><strong>Antecedentes</strong></h3><p>El <strong>Comité de Agenda</strong> tuvo su origen en el Comité de Agenda y Admisión, que fue nombrado en la Asamblea Mexicana (hoy Conferencia), celebrada del 11 al 13 de abril de 1974.</p><p>En la XIX Asamblea Mexicana, en su cuarta recomendación se anota: “Este comité recomienda que el Comité de Agenda y Admisiones cambie su denominación a Comité de Política, Agenda y Admisiones.</p><p>En la XL Conferencia Mexicana se divide en Comité de Política y Admisiones y Comité de Agenda. Y es de esta manera cómo funcionan estos comités en la actualidad.</p><p>Guía de funcionamiento del Comité de Agenda - p. 3 / 4 / 5 (derogado)</p><h3><strong>56ª Conferencia Mexicana</strong></h3><p>23. Se haga la adecuación del nombre del comité Agenda de la Junta de Servicios Generales, por el Comité de Conferencia, como viene en el Manual de EE.UU./Canadá.</p><p><strong>Dice: </strong>Agenda trabaja en la elaboración de procedimientos, del programa, orden del día de la Conferencia y en la selección del lema.</p><p><strong>Debe decir: </strong>Agenda:<br>Comité correspondiente de los Custodios: Conferencia. &lt;p&gt;Revisa y aprueba la planificación general y el contenido de la agenda para la Reunión Anual de la Conferencia. Considera las propuestas para lema de la Conferencia, mesas de trabajo, temas para presentación y debate, y el cuestionario de evaluación de la conferencia.</p><p>El Manual de Servicio de AA combinado con Doce Conceptos para el Servicio Mundial - p. 43</p><p><strong>Conferencia:</strong><br>Comité correspondiente de la Conferencia: Agenda.</p><p>Trabaja en los procedimientos, la agenda y el lema de la Reunión Anual de la Conferencia. Examina la distribución de la carga de trabajo entre los comités de la Conferencia. Considera innovaciones que fomenten una comunicación más efectiva entre los miembros de la Conferencia.</p><p>El Manual de Servicio de AA combinado con Doce Conceptos para el Servicio Mundial - p. 55</p><h3><strong>Preguntas frecuentes</strong></h3><ol><li><p><strong>¿En qué fecha se realiza la Conferencia Mexicana?</strong><br>La Conferencia de Servicios Generales está en funcionamiento todo el año, la reunión anual se celebra en la Ciudad de México en semana santa, la fecha es variable de acuerdo al calendario, es el punto culminante de las actividades de cada año.<br>El lema de Conferencia es utilizado en los documentos propios de la comunidad, se sugiere se coloque en la parte de abajo del mismo, cabe señalar que normalmente precede de la palabra “servicio”, normalmente atiende a motivar alguna posible solución a una problemática de servicio a nivel nacional.</p></li><li><p><strong>¿Cuándo y dónde es utilizada la denominación del año?</strong><br>Se utiliza durante todo el año, desde el 1 de enero de cada año, hasta el 31 de diciembre del mismo. Se coloca en todos los documentos de servicio, al inicio, debajo del membrete que utilice cada centro de servicio.<br>La temática de esta denominación nacional deriva de alguna posible solución a una problemática nacional, normalmente se precede a esta denominación el año en el cual se le dará vida a esta denominación.</p></li><li><p><strong>¿Qué son los temas de compartimiento general?</strong><br>Es un compartimiento que se realiza dentro de Conferencia, el expositor lo elige el comité de Conferencia de la JSG, se expone el tema en el pleno de Conferencia, posterior a él se sortean participaciones de los conferencistas de cinco minutos cada una para compartir sobre el mismo tema.<br>Este compartimiento se puede encontrar en el Reporte Final y puede ser compartido, leído y/o estudiado en el grupo, ya que se comparten elementos que ayuden a fortalecer los tres legados y la práctica de los principios que lleven a tener una estructura más sólida.</p></li><li><p><strong>¿Qué son las mesas de trabajo?</strong><br>Son mesas de análisis, integradas por los conferencistas, se realiza el análisis de problemas actuales a nivel nacional para encontrar las mejores alternativas de solución y fortalecimiento en la práctica de nuestros tres legados. Después de la inducción del tema, los integrantes de la mesa de trabajo participan con su punto de vista y aportación sobre el tema. En cada mesa de trabajo se elaborará, un acta en la cual constará el sentir de los integrantes de la mesa y que dará respuesta como posible solución y guía a nuestra comunidad, y que deberá aparecer en el Reporte final de cada Conferencia Mexicana.</p></li><li><p><strong>¿Cómo y cuándo se realiza la asignación de los delegados recién electos a los comités de Conferencia?</strong><br>De las áreas pares en un año y nones en otro se divide de manera equitativa los integrantes de los comités de Conferencia, se tiene un histórico del 2002 a la fecha, se trata de que sea rotativa esta asignación en lo más posible, hay varios factores que deben considerarse: no todas las regiones tienen el mismo número de áreas, hay áreas que han repetido un mismo comité, se trata de corregir esa situación, sin embargo llevará tiempo, ya que en algunos casos son varias las repeticiones; se debe cuidar que exista en todos los comités mínimo un área de cada región.<br>Los integrantes de los comités pueden ser entre 7 y 8, también de manera rotativa; esta asignación se realiza en el mes de Julio por parte del comité de Conferencia de la JSG.<br>Algunos delegados, además de servir en uno de los comités permanentes, también están asignados a un comité secundario como función suplementaria.</p></li><li><p><strong>¿Cuáles son las fechas para envío de informes de las áreas y de los comités de la JSG?</strong><br>En el mes de diciembre se envía una circular por parte del comité de Conferencia de la JSG, solicitando los informes a las áreas del país, anexando el formato establecido. Estos informes deben concentrarse en el segundo avance del cuadernillo de trabajo, por tanto, deben recibirse a más tardar durante la primera semana del mes de enero y así cumplir con la acción recomendable de enviar el avance a los conferencistas la segunda semana de dicho mes.<br>En el caso de los informes de los comités de la JSG, en el mismo mes de diciembre se envía la circular con la solicitud, para la recepción de los mismos tendremos hasta la primera semana de febrero, para cumplir con la acción recomendable que indica enviar el tercer avance del cuadernillo a los conferencistas en la segunda semana de febrero.</p></li></ol>');
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('comite-archivos-historicos', 'Comité de Archivos Históricos', '<h3><strong>Antecedentes</strong></h3><p>El Comité de Archivos de la Junta de Servicios Generales de la Central Mexicana de Servicios Generales de Alcohólicos Anónimos, AC, inició el sábado 29 de mayo de 2004, fecha en la que la reunión trimestral de la Junta de Custodios, emanó el Acuerdo 06-V-04, que dice: "Se acuerda la creación del Comité de Archivos Históricos".</p><h3><strong>Objetivo</strong></h3><p>Ofrecer a la comunidad un sentido de su propio pasado, y crear un contexto para la comprensión y valoración de los acontecimientos históricos importantes y tradicionales de Alcohólicos Anónimos.</p><p>Verificar la organización y preservación del material de interés histórico y que el almacenado este conforme a las normas profesionales y éticas más altas, y de acuerdo con las leyes de derechos de autor y la tradición del anonimato.</p><h3><strong>Misión</strong></h3><p>Facilitar a los miembros de Alcohólicos Anónimos® el acceso a los documentos y objetos históricos generados en nuestra comunidad a través del tiempo, de tal manera que el patrimonio de nuestra memoria histórica refleje la realidad y el mito no rebase los hechos, así como presentar acuerdos a la Junta de Servicios Generales sobre las acciones que deberán tomarse respecto al acceso y disposición del material disponible, para lo cual le corresponda especificar criterios aplicables a las normas de servicio, aprobar solicitudes de acceso a los materiales, sugerir procedimientos, asumir y mantener la responsabilidad final en materia de Archivos Históricos.</p><h3><strong>Comités de Archivos Históricos y Museos</strong></h3><p>Gran parte de las áreas del país, con el paso del tiempo, han ido conformando sus comités de archivos históricos, y como resultado han logrado establecer sus propios archivos y museos con los acervos de sus grupos, distritos y de las propias áreas.</p><p>Los archivos y museos de Alcohólicos Anónimos, representan el medio por el cual se puede renovar la dirección de nuestro propósito de llegar al alcohólico que aún está sufriendo, recopilando y preservando esa rica herencia.</p><h3><strong>Preguntas frecuentes</strong></h3><ol><li><p><strong>¿Por qué no hay mucho interés en este comité?</strong><br>Quizás por denominarse “Comité secundario”, algunos compañeros han interpretado que es menos importante que los comités llamados permanentes, pero en la realidad dentro de su autonomía, nuestra Junta de Servicios Generales antes Junta de Custodios, desde 2006, emitió el acuerdo 02-nov .-06, que dice: Se acuerda aprobar que el comité transitorio de Archivos Históricos de la Junta de Custodios pase a ser un comité permanente dentro de la Junta de Custodios.</p></li><li><p><strong>¿Cuál es el funcionamiento de los tótems?</strong><br>Es un dispositivo digital, su función es tener información histórica para que la comunidad de AA la pueda ver, conocer e interactuar con la historia, tiene 7 secciones: videos, trivias historia de AA, REDELA, Convenciones Nacionales, Reuniones Mundiales y Conferencias Mexicanas.</p></li><li><p><strong>¿Qué información de las áreas tienen archivos históricos nacionales?</strong><br>Tenemos la información de grupos, oficinas intergrupales y comités de áreas que se recibió desde los inicios la Oficina de Servicios Generales, así como libros históricos escritos por diversas áreas y entrevistas realizadas a veteranos y pioneros de la República Mexicana. Tenemos también la información de áreas contenidas en las asambleas y conferencias mexicanas.</p></li><li><p><strong>¿Por qué no se integra archivos históricos a los comités permanentes de la estructura y ya deja de ser secundario?</strong><br>Se han creado dos comités para considerar asuntos importantes a los que no hay que dedicar tanto tiempo como se dedica a los puntos del orden del día de los comités permanentes. Algunos delegados, además de servir en uno de los comités permanentes, también están asignados a estos comités como función suplementaria.</p></li><li><p><strong>¿Cuál es la fecha de registro del comité de Archivos Históricos?</strong><br>El sábado 29 de mayo de 2004, en la reunión de la trimestral de la Junta de Custodios emanó el acuerdo que dice: Acuerdo 06-V- 04. Se acuerda la creación del Comité de Archivos Históricos.</p></li><li><p><strong>¿Los grupos pueden mandar objetos al área del museo? ¿O Puros objetos del área?</strong><br>Se pueden proponer objetos de todos los niveles de la estructura, para que formen parte del acervo de los museos de áreas, siempre y cuando se consideren históricos. La decisión se puede tomar en las reuniones de área o del comité de archivos históricos de la misma, considerando el espacio que tengan.</p></li><li><p><strong>¿Qué procedimiento se lleva a cabo para elegir el nombre del museo?</strong><br>Eso lo decide la autonomía del grupo, distrito o área; pero una forma que se ha seguido es la de enviar una convocatoria para solicitar propuestas de nombre que se ponen a votación.</p></li><li><p><strong>¿Se pueden ingresar al museo documentos o fotos etc. de elaboración reciente?</strong><br>Si se relaciona con un hecho histórico importante, sí.</p></li><li><p><strong>¿Cómo recopilar la historia de mi grupo?</strong><br>Existe una Guía para la historia del grupo, la cual encontrarás en el Libro de trabajo de Archivos Históricos.</p></li><li><p><strong>¿Qué puedo hacer con la historia que tienen los veteranos?</strong><br>Queremos que haga énfasis en la sobriedad, más que en la bebida. El miembro de Alcohólicos Anónimos puede tal vez empezar contando la historia de cómo entrar en contacto inicialmente con el programa. En el Libro de trabajo de Archivos Históricos, podrás apoyarte con la Guía para la historia de veteranos, pioneros, mujeres, jóvenes, internos, etc.</p></li></ol>');
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('comite-ccp', 'Comité de Cooperación con la Comunidad Profesional (C.C.C.P.)', '<h4><strong>Antecedentes</strong></h4><p>La Cooperación entre la Comunidad Profesional y nuestra Comunidad se remonta hasta los comienzos de Alcohólicos Anónimos. Se ha dicho que la verdadera cuna de Alcohólicos Anónimos podría situarse en el consultorio del Dr. Carl Gustav Jung, cuando fue visitado en 1931 por su paciente alcohólico Rowland H. en busca de una solución para su problema alcohólico. Al serle recomendada cierta acción de carácter espiritual, Rowland acudió a los Grupos Oxford, donde tuvo la oportunidad de ayudar a Ebbie T., quien, a su vez, se puso en contacto con Bill W.</p><p>Aquí nos percatamos que una de las más destacadas personalidades de la ciencia y de los profesionales jugó un papel muy importante en nuestros orígenes.</p><p>A partir de 1935, la historia de Alcohólicos Anónimos se empezó a llenar de nombres de profesionales, que tuvieron influencia decisiva en el desarrollo de nuestra Comunidad. La lista empieza con algunos de los personajes más queridos y recordados, como lo son el Dr. Silkworth, la Hermana Ignacia, el Dr. Harry Tiebout, el Padre Edward Dowling, y muchos más, cuya labor fue tan importante, que hizo que Bill W. se refiriera a ellos como los verdaderos fundadores de Alcohólicos Anónimos.</p><p>En 1956, cuando fue formado el primer grupo de habla hispana en nuestro país, fue determinante la ayuda del psiquiatra y general el Dr. José González Varela, quien formaba parte de la dirección del Hospital Central Militar, en la Ciudad de México. Mientras que, en Mérida, Yuc., fue invaluable la ayuda del Doctor Carlos Rubio Rojas y del padre Roberto Menard en relación con el establecimiento de Alcohólicos Anónimos en el sureste de México.</p><h3><strong>Objetivo</strong></h3><p><strong>COOPERACIÓN CON LA COMUNIDAD PROFESIONAL </strong>(comité de los custodios: Cooperación con la Comunidad Profesional). Encargado de sugerir ideas o políticas y recomendar actividades que contribuyan a llevar el mensaje al alcohólico que aún sufre, compartiendo información sobre el programa de AA con grupos e individuos profesionales que tienen contacto con personas alcohólicas; fomentando así la comprensión y el respeto mutuo y la cooperación entre AA y la gente profesional, y elevando la conciencia de los miembros de AA y de grupos y organizaciones en cuanto a las varias formas de cooperar los unos con los otros sin afiliarse.</p><p><strong>Manual de Servicio de AA y Doce Conceptos para el Servicio Mundial - p. 112</strong></p><h3><strong>Preguntas frecuentes</strong></h3><ol><li><p><strong>¿Quién debe de firmar los convenios de tipo federal?</strong><br>El presidente de la Junta de Servicios Generales en función.</p></li><li><p><strong>¿Se pueden dar documentos o cartas a un imputado por acudir a un grupo de A.A.? ¿o para obtener su licencia de conducir?</strong><br>A.A. no proporciona ningún documento se contraponen con nuestros principios.</p></li><li><p><strong>¿Qué papel tiene este comité en sugerir candidatos a custodios clase “A”?</strong><br>Solamente hace propuestas al comité de Nominaciones.</p></li><li><p><strong>¿Se pueden firmar convenios a nivel municipal o estatal?</strong><br>Si, dándole vida a la 8ª recomendación de la 32ª conferencia que menciona, el comité del CCCP. de la Junta sea el responsable de coordinar en su totalidad lo siguiente: revisar, actualizar y darle seguimiento a todos los convenios de colaboración que tenemos firmados y los que en el futuro se lleguen a firmar.</p></li><li><p><strong>¿Tienen vigencia los convenios de colaboración?</strong><br>Con algunas instituciones si con otras no.</p></li><li><p><strong>¿Cómo se elige al coordinador del comité del CCCP de la Junta?</strong><br>Lo nombra el presidente de la Junta de Servicios Generales.</p></li><li><p><strong>¿Qué literatura debo regalar a un profesional?</strong><br>Libro Alcohólicos Anónimos, Boletín Ganar Aliados, y existe una gran variedad de folletos y trípticos de acuerdo con el profesionista que usted va a visitar, Favor de consultar lista de precios en esta misma página web.</p></li></ol>');
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('comite-finanzas', 'Comité de Finanzas', '<h2><strong>Comités de Finanzas</strong></h2><h3><strong>Objetivo</strong></h3><p><strong>FINANZAS (comité de los custodios: Finanzas). </strong>Revisa el presupuesto y los informes financieros de Oficina de Servicios Generales y Plenitud AA; revisa o emite recomendaciones a la Conferencia referentes a las finanzas. Está al tanto de las necesidades de la comunidad, incluyendo los presupuestos anuales y los ingresos necesarios para la realización de nuestra labor de servicio.</p><p><strong>Manual de Servicio de AA y Doce Conceptos para el Servicio Mundial - Edición 2023 - 2025 p.43</strong></p><h3><strong>Preguntas frecuentes</strong></h3><ol><li><p><strong>¿Para qué sirve el Comité de Finanzas de la JSG?</strong><br>Su principal responsabilidad es asegurarse de que no lleguemos a estar cortos de fondos y quebrarnos. Creando conciencia de la práctica de la Séptima Tradición a todos los niveles de servicio y estructurará los mecanismos adecuados para un control de ingresos y egresos para analizar los aspectos financieros de la OSG y Plenitud.</p></li><li><p><strong>¿Qué funciones principales tiene el Comité de Finanzas de la JSG?</strong><br>Este comité tiene la responsabilidad de examinar los resultados financieros de ambas corporaciones, y examina y aprueba, para su recomendación a la Junta de Servicios Generales, los presupuestos de la Central Mexicana de Servicios Generales, incluyendo los de la OSG y oficina Plenitud AA. Poco después de finalizar cada año, el excedente de efectivo que, después de cubrir sus necesidades operativas, tenga la Oficina de Servicios Generales y Oficina Plenitud AA, se transfiere al fondo de reserva de la Junta de Servicios Generales.</p></li><li><p><strong>¿A qué se debe que el fondo de reserva es a 11 meses y no a un año?</strong><br>En nuestro Manual de Servicio se establece como Fondo de reserva una cantidad equivalente a menos de un año de gastos de operaciones combinadas de OSG y OP y como límite máximo es de 12 meses, pero siempre debe estar por debajo del equivalente de 12 meses.</p></li><li><p><strong>¿Cuál es el objetivo del Fondo de Reserva?</strong><br>El propósito primordial del fondo de reserva, establecido por la Junta de custodios en 1994, es proveer los recursos financieros necesarios para mantener, en caso de emergencia o desastre, los servicios esenciales que prestan OSG y Oficina Plenitud AA; para sufragar gastos que excedan los recursos de OSG y Plenitud, como mejoras importantes en el inmueble o actualizaciones técnicas, y para dar tiempo a la Junta de servicios Generales y sus filiales operativas para formular los planes necesarios para ajustarse a algún cambio en las condiciones económicas o de otra índole, y poder implementarlos.</p></li><li><p><strong>¿En qué consiste el Plan anual de donativos y de dónde surge?</strong><br>El Plan anual de donativos fue aprobado en la 56ª conferencia mexicana, con el propósito de llegar a cubrir los gastos necesarios, para cumplir con los servicios que la Central Mexicana ofrece. Este Plan consiste en dividir el total de los gastos operativos de la OSG, entre el 60% de los miembros de la comunidad, con el fin de ser autosostenidos.</p></li><li><p><strong>¿De dónde sale la aportación de $410.00 del Plan anual?</strong><br>La cantidad de membresía al 60% (64,311 miembros), entre los gastos operativos (26,346,570) da $410.00 por persona.</p></li><li><p><strong>¿Cuáles son los donativos vigentes?</strong><br>Donativos voluntarios, por aniversario de compañero, donativos por aniversario de grupo, inscripción al delegado y donativo de placas.</p></li><li><p><strong>¿Sabes cuál es el origen de los diferentes rubros de donativos y en que Asamblea Mexicana (hoy Conferencia Mexicana), fueron aprobados y cuál es su objetivo?</strong><br><br><strong>Donativos voluntarios</strong>: en la 1a Asamblea Mexicana de 1969, se propuso a la Asamblea la aprobación para la formación de la Central Mexicana de Servicios Generales y solicitar a miembros y grupos de A.A. aportaciones económicas <strong>para el sostenimiento de la Central</strong>.<br>Tú como miembro de la comunidad puedes aportar $1.00 diario a tu OSG para su auto sostenimiento.<br><br><strong>Aniversario de miembros y grupos</strong>: este rubro fue aprobado en nuestra II Asamblea Mexicana (marzo de 1970). Actualmente dice la acción núm. 13 recomendada por la 53a Conferencia Mexicana en 2019, que las aportaciones voluntarias por concepto de aniversario sean de $150.00 por grupo y $100 por miembro.<br>Te invitamos a mandar tu donativo por aniversario tanto el personal como el de tu grupo…<br><br><strong>Inscripción de delegado a la conferencia</strong>: 3era. Recomendación de la 17ª Asamblea Mexicana (1983)- Se recomienda que los gastos que origina la Asamblea Mexicana se siga el plan de aportación que sea 50% para la OSG y 50% para las áreas.<br>Con el importe de esta inscripción se apoya a la OSG para cubrir gastos de hospedaje, alimentos, papelería, materiales, salarios, etc.</p></li></ol>');
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('comite-cip', 'Comité de Información Pública (C.I.P.)', '<p>En Alcohólicos Anónimos, Información Pública (I.P.) significa llevar el mensaje de recuperación al alcohólico que aún sufre informando del programa de A.A. al público en general. Llevamos el mensaje entablando contactos con los medios de comunicación, las escuelas, la industria, y otras organizaciones que pueden informar sobre la naturaleza y el propósito de A.A. y lo que puede hacer por los alcohólicos.</p><p><strong>Libro de Trabajo de Información Pública</strong></p><p><strong>Los miembros de comités de información pública comunican información de A.A. al público en general.</strong></p><p><strong>Los comités se enfocan en:</strong></p><ul><li><p>Dar presentaciones sobre A.A. a escuelas y organizaciones.</p></li><li><p>Brindar información sobre A.A. a través de materiales impresos y digitales.</p></li><li><p>Asegurar que los medios locales tengan información exacta sobre A.A. a través de anuncios de servicio público, entrevistas con protección del anonimato y carpetas de prensa.</p></li></ul><p><strong>Actividades sugeridas para los comités:</strong></p><ul><li><p>Coloque anuncios de servicio público en canales en línea, de radio y TV.</p></li><li><p>Envíe correos electrónicos a los colegios para comunicarles que hay presentaciones de IP para jóvenes disponibles, además de presentaciones en PowerPoint y otros medios digitales.</p></li><li><p>Coloque avisos de IP sobre reuniones abiertas en publicaciones de medios locales, especialmente durante la época de fiestas.</p></li><li><p>Envíe un correo electrónico de presentación a los medios locales, ofreciendo ser un recurso de información sobre A.A. y de entrevistas con protección de anonimato.</p></li><li><p>Ayude a los miembros a informarse mejor sobre la política de información pública de A.A.</p></li></ul><h3><strong>Preguntas frecuentes</strong></h3><ol><li><p><strong>¿Qué es el Libro de trabajo de Información Pública?</strong><br>Este libro de trabajo es material de servicio, que refleja la experiencia de los miembros de A.A. compartida con la <strong>Oficina de Servicios Generales</strong>. Los libros de trabajo de A.A. recopilan la experiencia práctica de los miembros de A.A. que trabajan en las diversas áreas de servicio. También reflejan los consejos de las Doce Tradiciones y de la Conferencia de Servicios Generales (EE.UU./Canadá).</p></li><li><p><strong>¿Cómo se trabaja la Información Pública?</strong><br>Las Doce Tradiciones son nuestras Tradiciones y la responsabilidad de preservarlas es nuestra. Muchos comités de I.P. dan gran importancia a informar a los miembros del comité sobre estas Tradiciones, lo que son y cómo nacieron. Con estos trabajos preliminares, los comités de I.P. pueden comunicar eficazmente los principios de A.A. al público en general y a los representantes de los medios de comunicación. No podemos esperar que otros comprendan y observen las Tradiciones si nosotros mismos no estamos bien informados. Lamentablemente, nos hemos dado cuenta de que la falta de información puede conducir a la intolerancia. Por ejemplo, si se viola el anonimato de un miembro de A.A. en los medios de comunicación, muy a menudo se produce como resultado de un malentendido. Enviar una nota cortés al miembro explicando la Tradición es útil; un juicio crítico y brusco no lo es. La cortesía y una explicación tranquila forman parte de la manera de actuar de A.A. Es de especial importancia tener una comprensión de todas las Tradiciones, en particular las Tradiciones de anonimato. El folleto “Comprendiendo el Anonimato” y la tarjeta de anonimato les pueden ser útiles para explicar claramente el principio de anonimato al público. (Recuerde: No constituye una ruptura de la Onceava Tradición identificarse privadamente como miembro de A.A. a las personas no-A.A. con quienes puede tener trato mientras está haciendo el trabajo de I.P.)</p></li><li><p><strong>¿Cuáles son los objetivos sugeridos para el comité de IP?</strong></p><ul><li><p>Asegúrense de que cada biblioteca pública tenga al menos un libro aprobado por la Conferencia, por ejemplo, el Libro Grande, Doce Pasos y Doce Tradiciones o Viviendo Sobrio, etc.</p></li><li><p>Informen a la Comunidad de cómo llegar a los que tienen impedimentos auditivos.</p></li><li><p>Pongan un estante de literatura en cada escuela secundaria, universidad, comisaría de policía, biblioteca y hospital de la zona y mantengan el estante debidamente provisto de literatura y horarios de reuniones.</p></li><li><p>Envíen una carta a las escuelas secundarias para ofrecer literatura de A.A. o proponer dar una presentación sobre A.A., lo que hacemos y lo que no hacemos.</p></li><li><p>Envíen una carta a las casas de convalecencia, casas de reposo y centros para jubilados de la zona para ofrecer literatura de A.A. o proponer dar una presentación sobre A.A.</p></li><li><p>Publiquen una lista de las reuniones abiertas de A.A. en los periódicos locales.</p></li><li><p>Pongan un pequeño anuncio (pagado si es necesario) en los periódicos locales durante la temporada de fiestas.</p></li><li><p>Trabajen con los periódicos (anonimato, Tradiciones) para generar interés en nuestra Comunidad.</p></li><li><p>Contesten a las solicitudes para hablar en reuniones no A.A. en su comunidad o la zona geográfica a la que pertenecen.</p></li><li><p>Pongan Anuncios de Servicio Público en las emisoras de radio y televisión.</p></li><li><p>Pongan los horarios de reuniones en la recepción de los hoteles, moteles y pensiones.</p></li><li><p>Participen en seminarios y convenciones de A.A. de la zona geográfica a la que pertenecen.</p></li><li><p>Combatan la apatía dentro de la Comunidad, encuentren un coordinador y gente interesada para lograr todo lo expuesto anteriormente, y de máxima importancia, mantengan su cordura y manténganse alejados del primer trago.</p></li></ul></li></ol>');
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('comite-cic', 'Comité de Instituciones Correccionales (C.I.C.)', '<h2><strong>Cómite en Instituciones Correcionales (C.I.C.)</strong></h2><h3><strong>Antecedentes</strong></h3><p>La Comunidad de Alcohólicos Anónimos tenía ya siete años de existencia cuando un alcaide pionero de la prisión de San Quintín, pidió a los AA de los alrededores que llevasen el mensaje a los alcohólicos en la propia institución. Era el año de 1942 y el alcaide, Clinton Duffy, dijo: &lt;&lt;Aunque el programa de AA solo ayudara a una persona, lo iniciaría igualmente&gt;&gt;. Hoy en día, hay centenares de grupos de AA detrás de los muros y numerosos Comités de Correccionales que les sirven.</p><p><strong>Libro de trabajo de Correccionales</strong></p><h3><strong>Objetivo</strong></h3><p><strong>INSTITUCIONES CORRECIONALES (Comité de Conferencia)<br>(Comité correspondientes a los custodios: Instituciones Correccionales)</strong></p><ul><li><p>Apoya a los miembros de AA para transmitir el mensaje a los alcohólicos bajo custodia.</p></li><li><p>Revisa todos los aspectos del servicio proporcionado a los grupos de AA en centros penitenciarios.</p></li><li><p>Emite recomendaciones sobre cualesquiera actualizaciones que requiera el material de Correccionales.</p></li><li><p>Aclara qué puede hacer AA y qué no, dentro del marco de las tradiciones, para ayudar a los Alcohólicos bajo custodia, tanto dentro de la institución como al momento de salir en libertad.</p></li></ul><p><strong>Manual de Servicio de AA y Doce Conceptos para el Servicio Mundial - p. 43</strong></p><p><strong>INSTITUCIONES CORRECIONALES (JSG)<br>(Comité correspondientes a la Conferencia: Instituciones Correccionales)</strong></p><ul><li><p>Elabora programas y materiales que apoyan la transmisión del mensaje a los Alcohólicos bajo custodia en instituciones correccionales.</p></li><li><p>Busca maneras de desarrollar y ampliar los contactos y servicios para personas bajo custodia que están a punto de ser liberadas.</p></li><li><p>Busca maneras de desarrollar y ampliar el Servicio de Correspondencia de Correccionales en la República Mexicana.</p></li></ul><p><strong>Manual de Servicio de AA y Doce Conceptos para el Servicio Mundial - p. 54</strong></p><h3><strong>Preguntas frecuentes</strong></h3><ol><li><p><strong>¿Los testimonios de los compañeros alcohólicos privados de la libertad tienen costo?</strong><br>Son sin donativo, se solicitan vía estructura y se envían a las áreas en sus pedidos literatura, donativos o placas.</p></li><li><p><strong>Los carnets para preliberados ¿tienen costo?</strong><br>Son sin donativo, y se solicitan vía estructura.</p></li><li><p><strong>¿Puedo tener acceso al convenio de colaboración entre los Centros Federales de Readaptación Social y AA?</strong><br>Está en la Intranet de la Central Mexicana el convenio con la SEGOB, para tener acceso a la intranet debes tener la contraseña por parte del delgado de tu área.</p></li><li><p><strong>Si soy un miembro AA experimentando nuevo servicio en las Instituciones Correccionales, ¿Cuál es la literatura que se sugiere leer primero?</strong><br><strong>Libro de trabajo de Correccionales</strong>, AA en las Instituciones Correccionales, Instituciones Correccionales con historiales de igual a igual, es mejor que estar sentado en una celda, Manual de servicio de AA. etc.</p></li><li><p><strong>¿Qué es lo primero que se debe observar al acudir a una Institución Correccional?</strong><br>Se sugiere buscar el apadrinamiento con quien haya experimentado el servicio, de preferencia acudir directamente al CIC en tu distrito. Como miembros de AA observar los reglamentos de cada institución correccional y estar dispuestos a sujetarse a ellos.</p></li><li><p><strong>¿Existe una guía para los contactos antes de la puesta en libertad?</strong><br>Si, lo podrás encontrar en el Libro de trabajo de Correccionales pág. 83. Ofrécete como voluntario para servir como contacto temporal cuándo las PPL van a ser puestos en libertad y llévalos a su primera reunión de AA al mundo de afuera.</p></li><li><p><strong>¿Cuáles son las características de un grupo AA institucional correccional?</strong><br>Te sugerimos leer la pág. 31 del Libro de trabajo de Correccionales, como dato un grupo de AA institucional correccional, es aquel que está conformado por miembros alcohólicos que tuvieron problemas con su forma excesiva de beber alcohol antes y/o al perder su libertad. Y que hoy se encuentran privadas de su libertad en algún centro penitenciario y que por su libre voluntad no pueden salir.</p></li><li><p><strong>¿Puedo solicitar testimonios de gratitud para los grupos AA institucionales correccionales, que celebran aniversario?</strong><br>Si, los solicitas vía estructura y sin ningún donativo, siguiendo las respuestas de las preguntas 2 y 3.</p></li><li><p><strong>¿Los grupos AA institucionales correccionales, también se dan de alta y se emite la placa de grupo?</strong><br>Sí, el alta del grupo se tramita vía estructura, al requerir la placa de grupo se realiza el donativo correspondiente para la emisión de la placa del grupo.</p></li><li><p><strong>¿Cómo puedo recibir la Revista Plenitud AA gratuitamente para los grupos de AA en institucionales correccionales?</strong><br>El grupo institucional correccional debe de estar debidamente registrado en el directorio nacional de la Central Mexicana, posteriormente la oficina plenitud enviará las revistas al área correspondiente y las hará llegar a los grupos institucionales correccionales.</p></li></ol>');
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('comite-literatura', 'Comité de Literatura', '<h3><strong>Objetivo</strong></h3><p>LITERATURA (comité de los custodios: Literatura) Este comité se ocupa principalmente de la literatura de recuperación. Los materiales relacionados con aspectos específicos de servicio, por ejemplo, material de correccionales, está preparado por el comité correspondiente. Estudia la necesidad de nueva literatura y materiales audiovisuales, revisa los folletos ya existentes y los borradores de los nuevos folletos según se van preparando y recomienda acciones especiales al comité de Literatura de los custodios. El comité de Literatura ha desempeñado un papel fundamental en la creación de los folletos y libros de AA. Nunca ha dudado en detener las actividades si le parece que la literatura de AA se va proliferando con demasiada rapidez, ni en recomendar a la editorial de AA a ponerse en acción cuando hay una auténtica necesidad de un nuevo libro o folleto. En años recientes ha contribuido a la creación de materiales audiovisuales.</p><p><strong>Manual de Servicio de AA y Doce Conceptos para el Servicio Mundial - p. 113</strong></p><h3><strong>Preguntas frecuentes</strong></h3><ol><li><p><strong>¿Cuándo saldrá a la comunidad el texto básico conmemorativo del 85° aniversario y cuál es su donativo?.</strong><br>Se inicia su distribución el 01 de abril en base al censo de ejemplares solicitados por cada una de las áreas y una vez concluida, estará disponible en la librería Bill W., y en el almacén de la OSG. Se acuerda asignar el donativo al Libro Alcohólicos Anónimos conmemorativo del 85 aniversario en $260.00 menos el 20% de descuento a las áreas, hasta agotar existencias.</p></li><li><p><strong>¿Cada que se edita un libro conmemorativo de AA qué trae de nuevo?</strong><br>En esta edición limitada conmemorativa del 85° aniversario el diseño, material y medidas son similares a la primera edición del libro publicado el 10 de abril de 1939, en la sección de historias personales se incluyen las 29 experiencias publicadas por primera vez en español.</p></li><li><p><strong>¿Cuántos códigos vigentes hay disponibles, actualizados con la nueva línea editorial?</strong><br>Actualmente están disponibles 16 libros (incluyendo El Manual de Servicio de AA combinado con Doce Conceptos para el Servicio Mundial código 106 y el Plan nacional de literatura código 119) 40 folletos (incluyendo el Manual de comités de literatura código 236 y el Manual de oficinas intergrupales código 246) y 12 trípticos (incluyendo el autodiagnóstico en braille código 286 y el tríptico Círculos de amor y servicio código 422).</p></li><li><p><strong>¿Por qué la literatura cuya licencia es otorgada por AA World Services, Inc, se imprime exactamente igual que el original en español?</strong><br>En cumplimiento a la 40 acción recomendable de la 50.ª Conferencia Mexicana (2016): «A la Junta de Servicios Generales, gire instrucciones a quien corresponda para que toda la literatura cuya licencia es otorgada por AA World Services, Inc., se imprima exactamente igual que el original en español, en caso de que requiera alguna adecuación se realice previa autorización de la AA World Services, Inc.».</p></li><li><p><strong>¿Para cuándo estará disponible el libro grande en la página web de la C.M.S.G.A.A.?</strong><br>Ya está disponible en archivo digital solo para lectura en la página Web de la CMSGAA.</p></li><li><p><strong>¿Sobre la impresión del compendio de temas sería impreso?</strong><br>No será impreso, debido a que en la 50.ª Conferencia Mexicana (2016) Se aprobó la 38ª acción recomendable que dice: «A la Junta de Servicios Generales, gire instrucciones a quien corresponda para que se edite el compendio de temas generales de asambleas y conferencias mexicanas, en versión digital, actualizada hasta la presente conferencia y se ponga a disposición de la comunidad en nuestra página web, de manera gratuita, actualizándose cada año después de la Conferencia».</p></li><li><p><strong>¿Por qué se exhibe la literatura aprobada de manera interactiva al sitio web de AA de la Central Mexicana?</strong><br>En cumplimiento a la 35 acción recomendable de la 55.ª Conferencia Mexicana (2021). «A la Junta de Servicios Generales, gire instrucciones a quien corresponda para que se agregue una sección al sitio web de la Central, que exhiba la literatura aprobada de manera interactiva, que muestre la sinopsis, portadas, a quien va dirigido, cronología y cualquier otra información de interés para su conocimiento».</p></li><li><p><strong>¿El compendio de las recomendaciones, ya no va a estar en intranet o es lo mismo la página web?</strong><br>La 3ª acción recomendable de la 48.ª Conferencia Mexicana (2014) dice: «A la Junta de Servicios Generales, gire instrucciones a quien corresponda para que el archivo digital del Compendio de recomendaciones, se ponga a disposición de la comunidad, sin donativo a través de la página Web de la Central Mexicana de Servicios Generales y que se actualice cada año al término de cada conferencia». Al tratarse de un material de servicio se encuentra en Intranet en los materiales del comité de literatura (ingresando desde la página Web en la sección miembros AA con nombre de usuario y contraseña).</p></li><li><p><strong>¿Qué se piensa hacer con la literatura que aún tiene el “enunciado de AA” pues ahora es preámbulo?</strong><br>Una vez agotadas las publicaciones existentes, el Enunciado de AA será sustituido por el Preámbulo de AA en todas las futuras publicaciones para dar cumplimiento a la acción recomendable de la 58.ª Conferencia Mexicana (2024).</p></li><li><p><strong>¿Por qué en septiembre la capacitación de literatura a coordinadores de las áreas? Deberían ser al inicio de cada año para que aprovechen la capacitación al inicio de su servicio, y ¿en septiembre ya casi es al terminar el servicio?</strong><br>En la reunión conjunta de la 58ª Conferencia Mexicana celebrada el día 24 de marzo de 2024, los comités de literatura de Conferencia y de la JSG acordaron que el 5° Encuentro de coordinadores de literatura de las áreas se realice en el mes de abril de 2025.</p></li><li><p><strong>¿Ha aumentado el desplazamiento de literatura después de las capacitaciones?</strong><br>En el 2023 se presenta un pequeño incremento en el desplazamiento de literatura, en relación del 2022.</p></li><li><p><strong>¿Qué resultado han tenido los encuentros nacionales no sólo económicos si no que resultados en la transmisión del mensaje ha tenido?</strong><br>Se realizó una encuesta a los coordinadores de literatura de las áreas que asistieron al 3er encuentro informando que: Se replicó en el 80% de las áreas reportando que en el 66% los resultados que produjo el 3er encuentro de literatura fueron positivos, el 96% contestaron que los temas de las mesas de trabajo y de las reuniones plenarias les fueron útiles. El manual del comité de literatura es utilizado en el 88% de las áreas, en el 73% de los distritos y en los grupos se utiliza solo en un 47 %. El plan nacional de literatura es utilizado en un 83 %, realizando juntas de estudio a nivel área en el 56%, en los distritos aumentan a 63 % y en los grupos disminuye su utilización al 59 %.</p></li><li><p><strong>¿Cuál es el objetivo que realice un encuentro de coordinadores de literatura de áreas?</strong><br>Favorecer el conocimiento, utilización y difusión de la literatura de Alcoholicos Anonimos, y motivar su lectura estudio y practica en los legados de Recuperación, Unidad y Servicio.</p></li><li><p><strong>¿Por qué ya no se elabora el folleto solo de los 12 pasos?</strong><br>En la 1ª acción recomendable de la 48.ª Conferencia Mexicana (2014) Se aprobó que: «A la Junta de Servicios Generales, gire instrucciones a quien corresponda para que se dejen de imprimir por separado los folletos Doce Pasos y Doce Tradiciones, y solo se imprima el libro Doce Pasos y Doce Tradiciones».</p></li><li><p><strong>En mi área hay mucha gente que no habla el idioma español, hablan en lengua indígena. Necesito traducir los trípticos y el libro grande. ¿Lo puedo hacer como área?</strong><br>Sí en la 43 Conferencia Mexicana (2009) se aprobó la 1.a sugerencia a las áreas que tengan etnias con lenguas o dialectos indígenas que, en la medida de sus posibilidades, traduzcan, graben y envíen en CD, a la Central Mexicana, material de nuestra literatura de Alcohólicos Anónimos, para tenerlo a disposición de las áreas que lo soliciten.</p></li><li><p><strong>¿Para cuándo estará disponible el libro AA en México parte 1 y parte 2?</strong><br>La primera parte ya se concluyó el proceso de producción y revisión, se solicitó al Indautor el ISBN para iniciar con su publicación. La segunda parte se encuentra en revisión por parte del comité de Archivos Históricos.</p></li><li><p><strong>¿Quién es el que tiene la calidad de revisión de la segunda parte de AA en México?</strong><br>La revisión de este código será realizada por el comité de literatura, el comité de archivos históricos y el departamento editorial conforme se establece en la política de publicaciones de la CMSGAA.</p></li><li><p><strong>¿Qué cuidados especiales se requieren para el manejo de los trípticos en Braille?</strong><br>Las producciones hápticas requieren de un manejo cuidadoso, de tal forma que los puntos en relieve no se aplasten. Por lo que su acondicionamiento deberá ser en cajas, para que los ejemplares no queden presionados.</p></li><li><p><strong>¿Por qué no hay en existencia en el almacén el libro transmítelo?</strong><br>El libro Transmítelo, se encuentra actualmente en producción estará disponible la tercera semana de abril de 2024.</p></li><li><p><strong>¿Cuándo se tendrá el libro de las tinieblas a la luz?</strong><br>Se están haciendo las gestiones necesarias para agilizar que el Indautor otorgue el ISBN solicitado, para iniciar con ello el proceso de impresión.</p></li><li><p><strong>¿Por qué tardan tanto las licencias? ¿Así son todas ellas?</strong><br>Las licencias tardan regularmente un plazo de 3 a 6 meses.</p></li><li><p><strong>¿El plan Nacional de Literatura tiene una ligera diferencia en los conceptos?</strong><br>Si actualmente se presentan algunas diferencias en la cuarta edición, ya se actualizó el archivo de producción del plan nacional de literatura para que en la quinta edición coincida en su totalidad con los párrafos en relación al código 106 El Manual de Servicio de AA combinado con Doce Conceptos para el Servicio Mundial edición 2023- 2025.</p></li><li><p><strong>¿De qué forma la Literatura, también lleva el mensaje?</strong><br>Hoy día, igual que en los primeros días de Alcohólicos Anónimos, el mensaje de AA de recuperación del alcoholismo se transmite por medio de un alcohólico que habla con otro. No obstante, desde la publicación de la primera edición del «Libro Grande» en 1939, la literatura ha desempeñado un importante papel en la propagación del mensaje de AA y en la difusión de información acerca del programa de los Doce Pasos de recuperación.</p></li><li><p><strong>¿Cuál es el propósito de los comités de Literatura?</strong><br>Es favorecer el conocimiento, utilización y difusión de la literatura de Alcohólicos Anónimos por medio de su adquisición, estudio y compartimiento, y de fomentar siempre la buena imagen de Alcohólicos Anónimos en la comunidad y propagar, entre aquellos que lo deseen, una nueva forma de vida.</p></li><li><p><strong>¿Cuáles son las funciones básicas de los comités de Literatura?</strong></p><ol><li><p>Mantener informados a los grupos y a los miembros de la asamblea de área o distrito, de toda la literatura aprobada por la conferencia, materiales audiovisuales y otros artículos especiales.</p></li><li><p>Familiarizarse con la información que aparece en la página web de AA de la Oficina de Servicios Generales (OSG).(www.aamexico.org.mx)</p></li><li><p>Proporcionar literatura en las funciones de servicio en el grupo, de área y de distrito.</p></li><li><p>Considerar sugerencias sobre propuestas, añadiduras y cambios en la literatura y materiales audiovisuales aprobados por la conferencia</p></li><li><p>Animar a los miembros de AA a leer y adquirir la literatura aprobada por la conferencia.</p></li></ol></li><li><p><strong>¿Qué es el Mural Orígenes?</strong><br>Es un cartel impreso de información y servicio del comité de Literatura de la Junta de Servicios Generales, publicado semestralmente por la Oficina de Servicios Generales de Alcohólicos Anónimos en México con la finalidad de motivar la lectura, adquisición, estudio y compartimiento de la literatura aprobada por Conferencia.</p></li></ol><p>Catálogo</p>');
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('comite-plenitud', 'Comité de Plenitud', '<h3><strong>Objetivo</strong></h3><p><strong>Plenitud AA</strong> es la revista nacional de <strong>Alcohólicos Anónimos</strong> , escrita, editada, ilustrada y leída por sus miembros y otros interesados ​​en el programa de recuperación, especialmente los que forman parte de la comunidad profesional. Es un eslabón entre los grupos y el alcohólico que está sufriendo. Iniciada en 1977, la revista se sostiene gracias a las aportaciones que se derivan de su adquisición y la de sus productos especiales.</p><p>Información del comité con el coordinador de área , distrito o grupo conforme a su servicio prestado al día.</p>');
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('comite-cta', 'Comité de Tratamiento y Accesibilidades (C.T.A.)', '<h3><strong>Antecedentes</strong></h3><p>Desde los comienzos de la comunidad de Alcohólicos Anónimos en 1935, hemos trabajado en cooperación con las instituciones de tratamiento. Bill Wilson era, él mismo, producto de una institución de tratamiento: el hospital Towns de la ciudad de Nueva York. Después de haber acumulado algunos meses de sobriedad, Bill volvió al Towns para trabajar con otros alcohólicos. Este evento señalo el comienzo del trabajo de Paso Doce de AA en los hospitales.</p><p>Después de haber logrado su sobriedad, el doctor Bob, un cirujano, se dio cuenta de la necesidad de tener un pabellón de alcoholismo en el hospital Santo Tomás, en Akron, Ohio, en donde trabajaba. Con la cariñosa ayuda y dedicación de la hermana Ignacia, el doctor Bob estableció un pabellón para alcohólicos; los dos ayudaron a más de cinco mil alcohólicos a lograr su sobriedad.</p><p><strong>Libro de trabajo de comités de Tratamiento - p.15</strong></p><p><strong>Comité de Tratamiento y Accesibilidades. Comité de la Junta de Servicios Generales CCP/Tratamiento y Accesibilidades.</strong></p><p>Procura crear la mutua comprensión y cooperación entre la comunidad y los grupos profesionales y las personas que se ocupan del alcoholismo y tratan con la persona alcohólica que aún sufre, para fomentar la aceptación de AA en hospitales, centros de rehabilitación e instituciones similares.</p><p>Estudia recursos para ayudar a los alcohólicos en tratamiento y a quienes procuran transmitirles el mensaje. Procura acercar el mensaje de AA a quienes se encuentran en comunidades remotas, obstaculizados por barreras de lenguaje, culturales o geográficas.</p><h3><strong>Preguntas frecuentes</strong></h3><ol><li><p><strong>¿Cuál es el origen de “El hombre en la cama”?</strong><br>Este cuadro “El hombre en la cama”, en que aparecen dos alcohólicos haciendo una visita de Paso Doce a un tercero, se puede encontrar en muchas salas de reunión de Alcohólicos Anónimos. Originalmente titulado “Llegamos a creer”, apareció por primera vez en el número de diciembre de 1955 del Grapavine. El artista, Bob M. un miembro de Alcohólicos Anónimos que, hacia ilustraciones para el Grapavine, dio el original a Bill W.</p></li><li><p><strong>¿Cuál fue el primer grupo institucional?</strong><br>En la ciudad de México, se llevó a cabo una junta de información en el pabellón de psiquiatría del hospital Central Militar, el 16 de diciembre de 1956, naciendo con ese evento el primer grupo institucional. El responsable del grupo “Hospital Central Militar” fue el médico psiquiatra y militar, José González Varela. Gracias a él y al grupo, se solucionó el problema de alcoholismo del mayor Joaquín Vargas Barrón, siendo éste el primer alcohólico recuperado de esta institución.</p></li><li><p><strong>¿Cuándo se instituyó de Tratamiento y Accesibilidades??</strong><br>En la 56ª Conferencia Mexicana de Servicios Generales, se aprobó adecuar el nombre del comité de Centros de Tratamiento al que se utiliza en la estructura de EE, UU y Canadá, siendo este "Comité de Tratamiento y Accesibilidades".</p></li><li><p><strong>¿Qué es un contacto temporal?</strong><br>En palabras sencillas, es un servidor de Alcohólicos Anónimos que trabaja con pacientes que son dados de alta, ayudándoles a llegar a nuestra comunidad. Código 131. Libro de trabajo de comités de Tratamiento página 63. Díptico 418 Voluntario para contacto temporal de AA/Unir las Orillas. Díptico 419 Solicitud de contacto temporal de AA/Unir las Orillas. 420 ¿A dónde voy de aquí? Estos materiales los puedes encontrar en la librería Bill W. en la oficina de la Central Mexicana de Servicios Generales de A.A. A.C.</p></li><li><p><strong>¿Qué significa “Uniendo las orillas”?</strong><br>Una de las travesías más “resbaladizas” del viaje hacia la sobriedad, se encuentra entre la puerta del hospital y la del grupo o la reunión de Alcohólicos Anónimos más cercana. El CTA propone unir las orillas entre el tratamiento y Alcohólicos Anónimos mediante el programa de contactos temporales. Libro de trabajo de comités de Tratamiento página 63.</p></li><li><p><strong>¿Qué es un grupo institucional?</strong><br>Un grupo institucional es aquel que se encuentra ubicado dentro de una institución hospitalaria, y que está conformado por AA de adentro, donde su estancia puede ser transitoria o permanente, y por AA de fuera.</p></li><li><p><strong>¿Qué es un grupo de Paso Doce?</strong><br>Es el que se encuentra instalado dentro de una clínica y está formado por AA de afuera. Su función es únicamente de carácter informativo.</p></li><li><p><strong>¿Puede un drogadicto o un adicto a las píldoras, que no se sea alcohólico, hacerse miembro de Alcohólicos Anónimos?</strong><br>No.</p></li><li><p><strong>¿Pueden los alcohólicos anónimos que han padecido tanto del alcoholismo como de cualquier otra adicción, y que han formado un grupo para ayuda a otros miembros que tienen problemas con la droga, referirse a este grupo especial como grupo de AA?</strong><br>No.</p></li><li><p><strong>¿Pueden los drogadictos o los adictos a las píldoras no alcohólicos, asistir a las reuniones cerradas?</strong><br>No.</p></li></ol><p><strong>Los comités de accesibilidades exploran, desarrollan y ofrecen recursos a los alcohólicos que enfrentan barreras significativas para recibir el mensaje de Alcohólicos Anónimos y participar en nuestro programa de recuperación. Queremos que A.A. esté disponible para todos los alcohólicos que extiendan su mano pidiendo ayuda.</strong></p>');
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('profesionales', 'Profesionales', '<h2>Alcohólicos Anónimos y los profesionales</h2><h2>Si usted es un profesional que está en contacto con personas que tienen problemas con su forma de beber alcohol, AA quiere cooperar con usted.</h2><img src="https://images.squarespace-cdn.com/content/v1/6687700cf37f2432cf9c2e77/1760329447307-WMCVXA1V3LXSLAG6D0YI/unsplash-image-pTrhfmj2jDA.jpg" alt="Hombre médico con bata blanca, gafas y estetoscopio cruzado frente a un fondo gris claro." loading="lazy"><h3>El objetivo primordial de AA es llevar su mensaje de recuperación al alcohólico que busca ayuda. Casi todos los tratamientos del alcoholismo tratan de ayudar al alcohólico a mantener su sobriedad. Sea cual sea el mismo destino, la recuperación de la persona.</h3><h2><strong>¿Cómo coopera AA con los profesionales?</strong></h2><h3>Alcohólicos Anónimos coopera con una amplia gama de profesionales no alcohólicos que, durante el curso de su carrera, muchas veces se encuentran con alcohólicos que están sufriendo. Ellos han sido una parte fundamental de AA desde sus comienzos.</h3><p>De hecho, AA quizás nunca habría despegado sin la ayuda de innumerables profesionales no alcohólicos comprometidos, como médicos, miembros del clero, docentes y oficiales del orden público, que se dieron cuenta rápidamente de la eficacia que AA mostró a la hora de ayudar a los alcohólicos a recuperarse.</p><p>Esta cooperación sigue siendo un pilar de la relación sostenida entre AA y los muchos profesionales de la salud mental que trabajan con alcohólicos y, en actividades recientes para mejorar y ampliar esa relación, se sugiere dentro de AA que se creen nuevos recursos acerca de AA con los profesionales de todos los sectores de la sociedad.</p><p><strong>Si</strong> <strong>desea saber más información al respecto, favor de comunicarse a:</strong></p><p><strong>contacto@aabcn02.org</strong></p><img src="https://images.squarespace-cdn.com/content/v1/6687700cf37f2432cf9c2e77/4ea5f933-a3b4-42e5-9c4f-4ece61b7ede7/El+objetivo+primordial+de+AA+es+llevar+su+mensaje+de+recuperaci%C3%B3n+al+alcoh%C3%B3lico+que+busca+ayuda.+Casi+todos+los+tratamientos+del+alcoholismo+tratan+de+ayudar+al+alcoh%C3%B3lico+a+mantener+su+sobriedad.+%282%29.png" alt="Alcohólicos Anónimos es una comunidad de personas que comparten su mutua experiencia, fortaleza y esperanza para resolver su problema común y ayudar a otros a recuperarse del alcoholismo. El único requisito para ser miembro de A.A. es el deseo de de" loading="lazy"> <img src="https://images.squarespace-cdn.com/content/v1/6687700cf37f2432cf9c2e77/2cb7fa1b-e31b-49a2-8635-0673e2cddf4a/Crystal-Ice-1-imgg-gi3-6bmnafba.png" alt="" loading="lazy"><h2><strong>Profesionales No alcohólicos que son parte de AA</strong></h2><h3><strong>Junta de Servicios Generales</strong></h3><p>En la historia de Alcohólicos Anónimos existen nombre de muchas personas no alcohólicos, profesionales médicos, juristas, economistas, contadores, psicólogos, trabajadores sociales, profesionales de prensa, radio y TV., que se han interesado por nuestro conocer Programa, dándolo a conocer a quienes han considerado que podría ayudarles y que han hecho que nuestra Comunidad haya sido cada día más conocida.</p><p>No sería exagerado decir que alguno de nosotros debemos nuestras vidas a estos profesionales. Vaya desde aquí para todos ellos nuestro más profundo agradecimiento.</p><p>Las políticas de relaciones públicas de AA es que los profesionales que son amigos de Alcohólicos Anónimos, es decir, que conocen y recomiendan el programa de AA, son los únicos que pueden aparecer a nivel público (prensa, radio, televisión y redes sociales) y que se pueden identificar con sus nombres completos y rostro, para invitar a otros profesionales a conocer los beneficios del Programa de AA, y público en General.</p><p>En México quienes representan a Alcohólicos Anónimos y los únicos facultades legalmente para hablar de la Central Mexicana de Servicios Generales de Alcohólicos Anónimos son estos profesionales, conocidos como custodios y custodias Clase A, es decir no Alcohólicos.</p><img src="https://images.squarespace-cdn.com/content/v1/6687700cf37f2432cf9c2e77/1760330782421-LHQI55QK9UCJVC85O52X/unsplash-image-i75WTJn-RBY.jpg" alt="" loading="lazy"><p><strong>Conoce a nuestro equipo</strong></p><ul><li><img src="https://images.squarespace-cdn.com/content/v1/6687700cf37f2432cf9c2e77/7265b5c6-b10e-497c-b539-cfa137aa940e/junta_1.jpg" alt="" loading="lazy"><h2>Mtro. Juan Arturo Sabines Torres</h2><p>Presidente de la Junta de Servicios Generales de Alcohólicos Anónimos, AC</p></li><li><img src="https://images.squarespace-cdn.com/content/v1/6687700cf37f2432cf9c2e77/caa2255a-bfb5-45d3-af49-d14f9eebb909/junta_2.jpg" alt="" loading="lazy"><h2>Dr. José Ángel Prado García</h2><p>Custodio clase A, Vicepresidente y Coordinador del comité de Información Pública de la Junta de Servicios Generales de Alcohólicos Anónimos, AC</p></li><li><img src="https://images.squarespace-cdn.com/content/v1/6687700cf37f2432cf9c2e77/908bfb7d-e52d-484b-8fea-8bccf1b0470f/junta_3.jpg" alt="" loading="lazy"><h2>CPC Araceli Arellano Fargeat</h2><p>Custodia Clase A y Coordinadora del Comité de Finanzas de la Junta de Servicios Generales de Alcohólicos Anónimos, AC</p></li><li><img src="https://images.squarespace-cdn.com/content/v1/6687700cf37f2432cf9c2e77/eb0d128c-0c4f-4360-a1ce-9ec28b90de39/junta_4.jpg" alt="" loading="lazy"><h2>Mtra. Vilma Mondragón García</h2><p>Custodia Clase A y Coordinadora del Comité de Instituciones Correccionales de la Junta de Servicios Generales de Alcohólicos Anónimos, AC</p></li><li><img src="https://images.squarespace-cdn.com/content/v1/6687700cf37f2432cf9c2e77/d23f8c98-b1c9-420e-ad17-f745f25f049d/junta_5.jpg" alt="" loading="lazy"><h2>Hna.Valentina Núñez López</h2><p>Custodia Clase A y Coordinadora del Comité de Cooperación con la Comunidad Profesional de la Junta de Servicios Generales de Alcohólicos Anónimos, AC</p></li><li><img src="https://images.squarespace-cdn.com/content/v1/6687700cf37f2432cf9c2e77/5d305a7c-7c22-4fd6-a7b4-ef8300ad249b/junta_6.jpg" alt="" loading="lazy"><h2>Psicóloga Irma Hernández Berber</h2><p>Custodio Clase A, Secretaria de la Junta de Servicios Generales y Coordinador del Comité de Tratamiento y Accesibilidades de la Junta de Servicios Generales de Alcohólicos Anónimos, AC</p></li></ul><h2><strong>¿Cómo recomendar la asistencia de AA?</strong></h2><h3>Las personas que creen tener un problema con la bebida pueden asistir a cualquier reunión de AA. Pueden sentarse, escuchar y aprender más acerca de la recuperación. O pueden compartir algo personal. Todo depende de ellos. Todos son bienvenidos. No tiene que pagar nada para asistir a reuniones.</h3><p>Los profesionales pueden observar las reuniones de AA para aprender más acerca de lo que hacemos. Si desea saber más acerca de las reuniones en la iamgen de abajo explicamos los dos tipos de reuniones.</p><h2>Tipos de reuniones</h2><p>Las reuniones aparecen listadas normalmente como reuniones “abiertas” o “cerradas”.</p><ul><li><p><strong>Las reuniones abiertas</strong> son para todos los que tienen un interés en el programa de recuperación del alcoholismo de Alcohólicos Anónimos. Las personas no alcohólicas pueden asistir a las reuniones abiertas como observadores.</p></li><li><p><strong>Las reuniones cerradas</strong> son solamente para los miembros de A.A. o para aquellos que tienen un problema con la bebida y un deseo de “dejar de beber”.</p></li></ul><p>En ambos tipos de reuniones se les puede pedir a los participantes que se limiten a hablar de asuntos que tengan que ver con la recuperación del alcoholismo.</p><p><br>Ya sean abiertas o cerradas, las reuniones de los grupos de A.A. son coordinadas por miembros de A.A. que determinan el formato de sus reuniones.</p><ul><li><a href="https://www.aabcn01.org/s/DOSSIER-DE-PRENSA-2024.pdf" target="_blank" rel="noopener">Dossier de prensa</a></li><li><a href="https://www.aabcn01.org/s/ONE-PAGE-AA-2022.pdf" target="_blank" rel="noopener">AA en una página</a></li><li><a href="https://www.aabcn01.org/s/Encuesta-Nacional-2023.pdf" target="_blank" rel="noopener">Información </a></li><li><a href="https://www.aabcn01.org/s/Carta-automantenimiento.pdf" target="_blank" rel="noopener">Cartas miembros</a></li></ul><h2>Si usted es un profesional<br>AA quiere cooperar con usted</h2><h3>Ayude a las personas con alcoholismo<br>a encontrar el camino a la recuperación.</h3><h3>Por favor proporcionemos<br>sus datos, nos comunicaremos.</h3>');
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('cartas', 'Cartas', '<h2><strong>Carta de mantenimiento automático</strong></h2><p><strong><em>A quien corresponda:</em></strong></p><p>En el curso de más de setenta años, Alcohólicos Anónimos ha considerado que el mejor camino para lograr el respeto de los demás estriba en su automantenimiento. Nuestra comunidad se ha sostenido con las contribuciones voluntarias de sus miembros durante toda su historia.</p><p>Todos los gastos que efectúan los integrantes, grupos, comités u oficinas de Alcohólicos Anónimos son enteramente cubiertos por los propios miembros. Alcohólicos Anónimos no realizan campañas para recolectar fondos, ni aceptan donativos oficiales, particulares o de personas ajenas a nuestra comunidad.</p><p>Dirigimos la presente con el único propósito de evitar que sean sorprendidos por personas que pretenden solicitar ayuda económica o material a nombre de Alcohólicos Anónimos.</p><p>Esperamos que esta aclaración sea de utilidad y aprovechamos para saludarlos y ponernos a su disposición, para que con su ayuda podamos realizar debidamente el único objetivo de Alcohólicos Anónimos: llevar el mensaje de Alcohólicos Anónimos al alcohólico que aún está sufriendo.</p><p><strong>Atentamente,<br>Comité de Información Pública</strong></p><p><a href="https://www.aabcn01.org/s/Carta-automantenimiento.pdf" target="_blank" rel="noopener">Descarga el archivo</a></p><h2><strong>Carta de anonimato</strong></h2><p><strong><em>A quien corresponda:</em></strong></p><p>La comunidad de Alcohólicos Anónimos recurre a su alto espíritu comprensivo para solicitar atentamente que nuestros miembros no sean fotografiados, ni sus nombres publicados en el medio de comunicación que ustedes tan dignamente dirigen.</p><p>Conservar el anonimato personal ante los medios públicos de comunicación, es la mejor garantía para los futuros miembros de que su identidad no será revelada. También nos ayuda para que ningún miembro se autodesigne representante o dirigente de Alcohólicos Anónimos.</p><p>La valiosa cooperación de los medios de comunicación a lo largo de los años ha sido formidable. De hecho, el programa de Alcohólicos Anónimos debe su difusión a periódicos, revistas, radio, televisión y cine. Por consiguiente, nuestra comunidad sí puede valerse de tan importantes medios para darse a conocer, más no así sus miembros.</p><p>Pueden tener la certeza de que los Alcohólicos Anónimos agradecen inmensamente su comprensión y continuo apoyo. Permítannos ofrecerles nuestra cooperación en cualquier momento.</p><p><strong>Atentamente,<br>Comité de Información Pública</strong></p><p><a href="https://www.aabcn01.org/s/Carta-de-anonimato.pdf" target="_blank" rel="noopener">Descarga el archivo</a></p><h2><strong>Lo que Alcohólicos Anónimos no hace</strong></h2><p><strong><em>A quien corresponda:</em></strong></p><p>Alcohólicos Anónimos no tiene opinión acerca de asuntos ajenos a sus actividades, y no desea intervenir en controversias; por consiguiente, nunca interviene en polémicas públicas.</p><p>Nuestro objetivo primordial es mantenernos sobrios y ayudar a otros alcohólicos a alcanzar el estado de sobriedad. Nuestra sociedad:</p><ol><li><p>No ofrece motivación inicial para la recuperación de los alcohólicos ni trata de persuadir a nadie para que pertenezca a la comunidad.</p></li><li><p>No mantiene archivos o historias clínicas.</p></li><li><p>No toma parte en investigaciones ni las patrocinadoras.</p></li><li><p>No se une a consejos de agencias sociales - aunque los miembros y grupos de AA frecuentemente cooperan con ellos.</p></li><li><p>No se trata de controlar a sus mienbros.</p></li><li><p>No hace diagnósticos médicos o psicológicos.</p></li><li><p>No proporciona servicios de hospitalización ni enfermería, medicamentos o cualquier tipo de tratamiento médico o psiquiátrico.</p></li><li><p>No ofrece servicios religiosos o espirituales.</p></li><li><p>No intervengan en propaganda o educación acerca del alcoholismo.</p></li><li><p>No proporciona casa, alimento, ropa, trabajo, dinero o cualquier otro tipo de servicio social o de caridad.</p></li><li><p>No proporciona consejos de tipo vocacional o doméstico.</p></li><li><p>No se acepta dinero ni ningún otro tipo de contribución proveniente de fuentes distintas a los Alcohólicos Anónimos.</p></li><li><p>No acepta dinero por sus servicios, ni contribuciones de fuentes no-AA.</p></li><li><p>No se suministran cartas de recomendación a las juntas de libertad condicional, abogados, funcionarios de los tribunales, agencias sociales, trabajadores.</p></li></ol><p>Esperamos que esta aclaración sea de utilidad. Alcohólicos Anónimos agradece su comprensión. Permitanos ofrecer nuestra cooperación en cualquier momento.</p><p><strong>Atentamente,<br>Comité de Información Pública</strong></p><p><a href="https://www.aabcn01.org/s/Lo-que-AA-no-hace.pdf" target="_blank" rel="noopener">Descarga el archivo</a></p>');
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('prensa', 'Prensa y medios', '<h2><strong>Para los medios de comunicación</strong></h2><p>Los reporteros, periodistas y en general los medios de comunicación masiva han sido y serán los principales informadores del funcionamiento de AA y de la ayuda que proporciona a las personas que sufren de la enfermedad del alcoholismo.</p><p>En tal sentido, podemos seguir colaborando con ustedes, si desean más información sobre Alcohólicos Anónimos o la experiencia de algún testimonio de recuperación para sus trabajos periodísticos: artículos, entrevistas, reportajes o participaciones en programas de radio o televisión, pueden ponerse en contacto con nosotros. en la siguiente cuenta de correo: comunicacionsocial@aamexico.org.mx .</p><h3><strong>Información relevante</strong></h3><p>La Central Mexicana de Servicios Generales de Alcohólicos Anónimos, AC es la representación legal de Alcohólicos Anónimos en México. Es también la única reconocida por Alcoholics Anonymous World Services, Inc. con sede en la ciudad de Nueva York en los Estados Unidos de América y es la única autorizada para editar, publicar y distribuir la literatura de AA en nuestro país.</p><p>También es la única autorizada para ostentar legalmente el nombre de “Alcohólicos Anónimos” y sus logotipos característicos (círculo con triángulo inscrito en todas sus variantes), así como AA y (doble A) las cuales no son de dominio público, son marcas registradas ante. el Instituto Nacional de la Propiedad Industrial (IMPI) y protegidas por las leyes mexicanas.</p><p>La Central Mexicana de Servicios Generales de Alcohólicos Anónimos, AC está conformada por una red de más de 14,500 grupos de ayuda mutua y con aproximadamente 121 mil miembros en recuperación en todo el país, todos los grupos sesionan en terapia grupal de hora y media al día. y de servicios totalmente gratuitos.</p><h3><strong>Carta de anonimato</strong></h3><p>A quien corresponda:</p><p>La comunidad de Alcohólicos Anónimos , recurre a su alto espíritu comprensivo para solicitar atentamente que nuestros miembros no sean fotografiados ni publicados sus nombres completos, en el medio de comunicación que usted tan dignamente dirige.</p><p>Alcohólicos Anónimos no es una sociedad secreta, aunque tampoco cumpliría su objetivo si estuviera formada sólo por exhibicionistas.</p><p>Conservar el anonimato personal ante los medios públicos de información, es la mejor garantía para los futuros miembros de que su identidad no será revelada; También sirve para que ningún miembro pretenda pregonarse como representante o dirigente de Alcohólicos Anónimos.</p><p>La valiosa cooperación de la publicidad a lo largo de los años ha sido formidable. De hecho, el programa de Alcohólicos Anónimos debe su difusión a periódicos, revistas, radio, televisión y cine. Por consiguiente, nuestra comunidad sí puede valerse de tan importantes medios de comunicación para darse a conocer, pero no así sus miembros.</p><p>Pueden tener la certeza de que los Alcohólicos Anónimos agradecen inmensamente su comprensión y continuo apoyo. Permítanos ofrecer nuestra absoluta cooperación con ustedes en cualquier momento.</p><p><strong>Cordialmente<br>Comité de Información Pública</strong></p><h3><strong>Carta de No Controversia</strong></h3><p>A quien corresponda:</p><p>Es evidente que la armonía, la seguridad y la efectividad futura de Alcohólicos Anónimos dependerán, en gran parte, de conservar una actitud que no sea agresiva, sino pacífica en todas nuestras relaciones públicas.</p><p>Alcohólicos Anónimos no tiene opinión acerca de asuntos ajenos a sus actividades, no desea intervenir en controversias; por consiguiente su nombre nunca debe mezclarse en polémicas públicas.</p><p>Nuestro objetivo primordial es mantenernos sobrios y ayudar a otros alcohólicos a alcanzar el estado de sobriedad.</p><p><strong>Cordialmente<br>Comité de Información Pública</strong></p><h3><strong>Carta de Automantenimiento</strong></h3><p>A quien corresponda:</p><p>A través de más de 88 años, Alcohólicos Anónimos ha considerado que el mejor camino para lograr el respeto de los demás, estriba en su automantenimiento.</p><p>Nuestra comunidad se ha sostenido con las contribuciones ordinarias de sus miembros.</p><p>Todos los servicios que efectúan tanto integrantes, grupos, comités u oficinas de Alcohólicos Anónimos , son enteramente gratuitos. Alcohólicos Anónimos no realizan campañas para recolectar fondos, ni aceptan donativos oficiales, particulares o de personas ajenas a nuestra comunidad.</p><p>Dirigimos la presente con el único propósito de evitar que sean sorprendidos por personas que pretenden solicitar ayuda económica o material a nombre de Alcohólicos Anónimos.</p><p>Esperamos que esta aclaración sea de utilidad y aprovechamos para saludarles y ponernos a su disposición, para que con su ayuda podamos realizar el único objetivo de Alcohólicos Anónimos: "llevar el mensaje de Alcohólicos Anónimos que aún está sufriendo".</p><p>Cordialmente<strong><br>Comité de Información Pública</strong></p><p>Boletín de prensa<strong> | </strong><a href="https://www.aabcn01.org/s/DOSSIER-DE-PRENSA-2024.pdf" target="_blank" rel="noopener">Dossier de prensa</a><strong> | </strong><a href="https://www.aabcn01.org/s/ONE-PAGE-AA-2022.pdf" target="_blank" rel="noopener">AA en una página | </a></p>');
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('faq', 'Preguntas frecuentes', '<p><strong>1. ¿Qué es Alcohólicos Anónimos (AA)? </strong><br>Alcohólicos Anónimos es una comunidad de personas que comparten su experiencia, fuerza y esperanza para resolver juntos el problema del alcoholismo. El único requisito para ser miembro es el deseo de dejar de beber, y no se cobra ninguna cuota por pertenecer</p><p><strong>2. ¿Qué es el alcoholismo y cómo se define en AA? </strong><br>AA considera el alcoholismo como una enfermedad progresiva, donde existe una alergia física al alcohol combinada con una obsesión mental. La recuperación requiere aceptación y apoyo mutuo.</p><p><strong>3. ¿Cómo puedo saber si soy verdaderamente alcohólico? </strong><br>Solo tú puedes tomar esa decisión. Si has intentado controlar tu consumo sin éxito o si el alcohol interfiere en tu vida diaria, podrías ser alcohólico. En AA se evalúa a partir del deseo de cambiar.</p><p><strong>4. ¿Cómo me uno a AA? ¿Existe algún proceso formal?</strong><br>No necesitas llenar formularios ni pagar cuotas. Simplemente comienza asistiendo a una reunión local. No hay registro oficial; tu participación es voluntaria.</p><p><strong>5. ¿Qué sucede en una reunión de AA? </strong><br>En una reunión abierta, cualquier persona puede asistir, escuchar historias o compartir experiencias. En las reuniones cerradas participan sólo personas con problemas con la bebida. No se revela la identidad de los participantes.</p><p><strong>6. ¿Puedo asistir acompañado de un familiar o amigo? </strong><br>Sí, puedes llevar personas que no sean alcohólicas a las reuniones abiertas. Esto ayuda a que comprendan el programa y puedan apoyar efectivamente en casa.</p><p><strong>7. ¿Con qué frecuencia debes asistir a las reuniones? </strong><br>No hay una regla estricta, pero se recomienda al menos una reunión semanal. Muchos nuevos participantes asisten con más frecuencia al inicio para fortalecer su compromiso.</p><p><strong>8. ¿Es necesario asistir a reuniones toda la vida? </strong><br>No es obligatorio. Aunque muchos optan por una asistencia regular a largo plazo, cada persona decide según sus necesidades y bienestar en el presente.</p><p><strong>9. ¿Qué son los “Doce Pasos” en AA? </strong><br>Los Doce Pasos son el fundamento del programa de recuperación. No son obligatorios, pero quienes los adoptan con sinceridad suelen obtener mayores beneficios en su proceso personal de sobriedad.</p><p><strong>10. ¿Cómo ayuda realmente AA si ya he tocado fondo? </strong><br>AA ha demostrado ser efectivo sin importar los antecedentes económicos, sociales o legales. Solo se requiere el deseo genuino de recuperar el control y vivir sin alcohol.</p>');
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('aviso', 'Aviso de privacidad', '<p><strong>Responsable:</strong> Área 64 Región 02 (Mexicali, Baja California)<br><strong>Domicilio:</strong> [DIRECCIÓN DE LA OFICINA DE ÁREA], Mexicali, Baja California, México<br><strong>Correo:</strong> contacto@aabcn02.org<br><strong>Teléfono:</strong> <strong>[TELÉFONO DE OFICINA]</strong></p><h2>1) Datos personales que recabamos</h2><p>Podemos solicitar: nombre, teléfono, correo electrónico y, de forma opcional, municipio/colonia para orientarte a un grupo cercano. No solicitamos datos sensibles.</p><h2>2) Finalidades del tratamiento</h2><ul><li><p><strong>Atención y orientación</strong> relacionada con Alcohólicos Anónimos.</p></li><li><p><strong>Canalizarte</strong> con grupos y servicios del Área 64 Región 02.</p></li><li><p><strong>Responder consultas</strong> realizadas por teléfono, correo o formularios del sitio.</p></li><li><p><strong>Estadística interna</strong> y mejora de servicios (datos disociados).</p></li></ul><p>Finalidades <strong>opcionales</strong> (marca tu preferencia cuando aplique):</p><ul><li><p>Información de eventos de servicio (talleres, juntas, convenciones).</p></li><li><p>Invitaciones a actividades informativas.</p></li></ul><h2>3) Fundamento legal</h2><p>Tratamos tus datos conforme a la <strong>Ley Federal de Protección de Datos Personales en Posesión de los Particulares</strong> y su Reglamento.</p><h2>4) Transferencias</h2><p>No transferimos tus datos a terceros con fines comerciales. En caso de canalización, <strong>solo compartimos lo estrictamente necesario</strong> con servidores de distrito o grupo para cumplir la finalidad de contacto.</p><h2>5) Ejercicio de derechos ARCO</h2><p>Puedes <strong>acceder, rectificar, cancelar u oponerte</strong> al tratamiento de tus datos (ARCO), así como <strong>revocar tu consentimiento</strong> o <strong>limitar su uso o divulgación</strong>. Solicítalo en cualquier momento por correo a <strong>contacto@aabcn02.org </strong>indicando:</p><ul><li><p>“<em>Nombre completo y medio para notificaciones.</em>”</p></li></ul><ul><li><p>“<em>Descripción precisa del derecho que deseas ejercer.</em>”</p></li><li><p>“<em>Identificación oficial digital (si aplica).</em>”</p></li></ul><p>“<strong>Te responderemos en un plazo máximo de 20 días hábiles.</strong>”</p><h2>6) Conservación y seguridad</h2><p>Conservamos los datos <strong>solo el tiempo necesario</strong> para las finalidades indicadas y aplicamos medidas administrativas y técnicas razonables para protegerlos contra pérdida, uso indebido o acceso no autorizado.</p><h2>7) Uso de cookies y tecnologías similares</h2><p>El sitio puede emplear cookies con fines de funcionalidad y análisis. Puedes deshabilitarlas en tu navegador. Si usamos herramientas de terceros (p. ej., reCAPTCHA, mapas, analítica), éstas pueden colocar sus propias cookies conforme a sus políticas.</p><h2>8) Cambios al Aviso</h2><p>Podremos actualizar este Aviso para reflejar mejoras o cambios normativos. La versión vigente estará disponible en <a href="/pagina?p=aviso"><strong>https://aabcn02.org/pagina?p=aviso</strong></a> con la fecha de última actualización.</p><p><strong>Fecha de última actualización:</strong> 9/10/2025</p>');
INSERT OR REPLACE INTO paginas (slug, titulo, contenido) VALUES ('contacto', 'Contacto', '<h2>Escríbenos</h2><p><strong>Correo:</strong> <a href="mailto:contacto@aabcn02.org">contacto@aabcn02.org</a></p><p><strong>Teléfono:</strong> [TELÉFONO DE OFICINA]</p><p><strong>Oficina de área:</strong> [DIRECCIÓN DE LA OFICINA DE ÁREA], Mexicali, Baja California, México</p><p>Si buscas un grupo, consulta el <a href="/directorio">Directorio de grupos</a> o el <a href="/mapa">mapa</a>. Preséntate en cualquier grupo diciendo que deseas información para dejar de beber.</p>');
